import 'package:supabase_flutter/supabase_flutter.dart'; import '../../../../core/utils/id_generator.dart'; import '../../../../core/month_scope/accounting_month_scope.dart'; class PayrollRemoteDataSource { PayrollRemoteDataSource(this.client); final SupabaseClient client; Future<List<Map<String,dynamic>>> list() async { final m=AccountingMonthScope.start; final next=DateTime(m.year,m.month+1,1); return List<Map<String,dynamic>>.from(await client.from('payroll_records').select().gte('month_start','${m.year}-${m.month.toString().padLeft(2,'0')}-01').lt('month_start','${next.year}-${next.month.toString().padLeft(2,'0')}-01').order('month_start',ascending:false).limit(1000)); } Future<String> create({required String employeeName,required DateTime monthStart,required double baseSalary,required double commission,required double deductions,required double bonus,required double overtimeHours,required double overtimeRate}) async => '${await client.rpc('sws_create_payroll_record',params:{'p_employee_name':employeeName.trim(),'p_month_start':'${monthStart.year}-${monthStart.month.toString().padLeft(2,'0')}-01','p_base_salary':baseSalary,'p_commission':commission,'p_deductions':deductions,'p_bonus':bonus,'p_overtime_hours':overtimeHours,'p_overtime_rate':overtimeRate})}'; Future<String> pay({required String payrollId,required double amount,required String method,required String note}) async { final result=await client.rpc('sws_pay_payroll',params:{'p_payroll_id':payrollId,'p_amount':amount,'p_payment_method':method,'p_note':note,'p_idempotency_key':IdGenerator.uuidV4(),'p_effective_at':DateTime.now().toUtc().toIso8601String()}); final id='$result'; final row=Map<String,dynamic>.from(await client.from('financial_movements').select('receipt_no').eq('id',id).single()); return '${row['receipt_no'] ?? id}'; } Future<void> update({required String payrollId,required String employeeName,required double baseSalary,required double commission,required double deductions,required double bonus,required double overtimeHours,required double overtimeRate}) async { await client.rpc('sws_update_payroll_record',params:{'p_payroll_id':payrollId,'p_employee_name':employeeName.trim(),'p_base_salary':baseSalary,'p_commission':commission,'p_deductions':deductions,'p_bonus':bonus,'p_overtime_hours':overtimeHours,'p_overtime_rate':overtimeRate}); } Future<void> delete({required String payrollId,required String reason}) async { await client.rpc('sws_delete_payroll_record',params:{'p_payroll_id':payrollId,'p_reason':reason.trim()}); } }
